DELETE FROM foods f
USING seed_food_names v, foods twin
WHERE f.name = v.old_name
  AND f.brand IS NOT DISTINCT FROM v.old_brand
  AND twin.name = v.new_name
  AND twin.brand IS NOT DISTINCT FROM v.new_brand
  AND twin.search_alias = concat_ws(' ', v.old_brand, v.old_name)
  AND NOT EXISTS (SELECT 1 FROM meal_entries m WHERE m.food_id = f.id)
  AND NOT EXISTS (SELECT 1 FROM meal_combo_items i WHERE i.food_id = f.id);

UPDATE foods f
SET name = v.new_name,
    brand = v.new_brand,
    category = CASE WHEN f.category IS NOT DISTINCT FROM v.old_category THEN v.new_category ELSE f.category END,
    search_alias = concat_ws(' ', v.old_brand, v.old_name),
    updated_at = now()
FROM seed_food_names v
WHERE f.name = v.old_name
  AND f.brand IS NOT DISTINCT FROM v.old_brand
  AND NOT EXISTS (
    SELECT 1 FROM foods g
    WHERE g.name = v.new_name AND g.brand IS NOT DISTINCT FROM v.new_brand AND g.id <> f.id
  );

DROP TABLE seed_food_names;
